import{_ as l,a0 as p,w as r,s as d,I as i,x as a,a1 as t,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"循序漸進學習如何在 MariaDB 中配置主從複製 | LCTT x X-CMD","titleTemplate":false,"description":"循序漸進學習如何在 MariaDB 中配置主從複製 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"循序漸進學習如何在 MariaDB 中配置主從複製 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"循序漸進學習如何在 MariaDB 中配置主從複製 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171112 Step by Step guide for creating Master Slave replication in MariaDB","title":"循序漸進學習如何在 MariaDB 中配置主從複製","tag":"201802","desc":""},"relativePath":"201802/20171112 Step by Step guide for creating Master Slave replication in MariaDB.md","filePath":"[post].md"}'),h={name:"201802/20171112 Step by Step guide for creating Master Slave replication in MariaDB.md"};function g(c,s,k,b,u,m){const e=p("Link");return r(),d("div",null,[s[21]||(s[21]=i("h1",{id:"循序漸進學習如何在-mariadb-中配置主從複製",tabindex:"-1"},[a("循序漸進學習如何在 MariaDB 中配置主從複製 "),i("a",{class:"header-anchor",href:"#循序漸進學習如何在-mariadb-中配置主從複製","aria-label":"Permalink to “循序漸進學習如何在 MariaDB 中配置主從複製”"},"​")],-1)),i("p",null,[s[2]||(s[2]=a("在我們前面的教程中，我們已經學習了 ",-1)),t(e,{href:"https://linux.cn/article-8320-1.html"},{default:n(()=>[...s[0]||(s[0]=[a("如何安裝和配置 MariaDB",-1)])]),_:1}),s[3]||(s[3]=a("，也學習了 ",-1)),t(e,{href:"https://linux.cn/article-9306-1.html"},{default:n(()=>[...s[1]||(s[1]=[a("管理 MariaDB 的一些基礎命令",-1)])]),_:1}),s[4]||(s[4]=a("。現在我們來學習，如何在 MariaDB 服務器上配置一個主從複製。",-1))]),s[22]||(s[22]=i("p",null,"複製是用於為我們的資料庫創 建多個副本，這些副本可以在其它資料庫上用於運行查詢，像一些非常繁重的查詢可能會影響主資料庫服務器的性能，或者我們可以使用它來做數據冗餘，或者兼具以上兩個目的。我們可以將這個過程自動化，即主服務器到從服務器的複製過程自動進行。執行備份而不影響在主服務器上的寫操作。",-1)),s[23]||(s[23]=i("p",null,"因此，我們現在去配置我們的主-從複製，它需要兩台安裝了 MariaDB 的機器。它們的 IP 地址如下：",-1)),s[24]||(s[24]=i("ul",null,[i("li",null,[i("strong",null,"主服務器 -"),a(" 192.168.1.120 "),i("strong",null,"主機名 -"),a(" master.ltechlab.com")]),i("li",null,[i("strong",null,"從服務器 -"),a(" 192.168.1.130 "),i("strong",null,"主機名 -"),a(" slave.ltechlab.com")])],-1)),i("p",null,[s[6]||(s[6]=a("MariaDB 安裝到這些機器上之後，我們繼續進行本教程。如果你需要安裝和配置 MariaDB 的教程，請查看",-1)),t(e,{href:"https://linux.cn/article-8320-1.html"},{default:n(()=>[...s[5]||(s[5]=[i("strong",null,"這個教程",-1)])]),_:1}),s[7]||(s[7]=a("。",-1))]),s[25]||(s[25]=o(`<h3 id="第-1-步-主服務器配置" tabindex="-1">第 1 步 - 主服務器配置 <a class="header-anchor" href="#第-1-步-主服務器配置" aria-label="Permalink to “第 1 步 - 主服務器配置”">​</a></h3><p>我們現在進入到 MariaDB 中的一個命名為 <code>important</code> 的資料庫，它將被複制到我們的從服務器。為開始這個過程，我們編輯名為 <code>/etc/my.cnf</code> 的文件，它是 MariaDB 的配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/my.cnf</span></span></code></pre></div><p>在這個文件中找到 <code>[mysqld]</code> 節，然後輸入如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[mysqld]</span></span>
<span class="line"><span>log-bin</span></span>
<span class="line"><span>server_id=1</span></span>
<span class="line"><span>replicate-do-db=important</span></span>
<span class="line"><span>bind-address=192.168.1.120</span></span></code></pre></div><p>保存並退出這個文件。完成之後，需要重啓 MariaDB 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart mariadb</span></span></code></pre></div><p>接下來，我們登入我們的主服務器上的 Mariadb 實例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><p>在它上面創建一個命名為 <code>slaveuser</code> 的為主從複製使用的新用户，然後運行如下的命令為它分配所需要的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STOP SLAVE;</span></span>
<span class="line"><span>GRANT REPLICATION SLAVE ON *.* TO  &#39;slaveuser&#39;@&#39;%&#39; IDENTIFIED BY &#39;iamslave&#39;;</span></span>
<span class="line"><span>FLUSH PRIVILEGES;</span></span>
<span class="line"><span>FLUSH TABLES WITH READ LOCK;</span></span>
<span class="line"><span>SHOW MASTER STATUS;</span></span></code></pre></div><p><strong>注意：</strong> 我們配置主從複製需要 <code>MASTER_LOG_FILE</code> 和 <code>MASTER_LOG_POS</code> 的值，它可以通過 <code>show master status</code> 來獲得，因此，你一定要確保你記下了它們的值。</p><p>這些命令運行完成之後，輸入 <code>exit</code> 退出這個會話。</p><h3 id="第-2-步-創建一個數據庫備份-並將它移動到從服務器上" tabindex="-1">第 2 步 - 創建一個數據庫備份，並將它移動到從服務器上 <a class="header-anchor" href="#第-2-步-創建一個數據庫備份-並將它移動到從服務器上" aria-label="Permalink to “第 2 步 - 創建一個數據庫備份，並將它移動到從服務器上”">​</a></h3><p>現在，我們需要去為我們的資料庫 <code>important</code> 創建一個備份，可以使用 <code>mysqldump</code> 命令去備份。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p important &gt; important_backup.sql</span></span></code></pre></div><p>備份完成後，我們需要重新登錄到 MariaDB 資料庫，並解鎖我們的表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>$ UNLOCK TABLES;</span></span></code></pre></div><p>然後退出這個會話。現在，我們移動我們剛才的備份到從服務器上，它的 IP 地址是：192.168.1.130。</p><p>在主服務器上的配置已經完成了，現在，我們開始配置從服務器。</p><h3 id="第-3-步-配置從服務器" tabindex="-1">第 3 步：配置從服務器 <a class="header-anchor" href="#第-3-步-配置從服務器" aria-label="Permalink to “第 3 步：配置從服務器”">​</a></h3><p>我們再次去編輯（從服務器上的） <code>/etc/my.cnf</code> 文件，找到配置文件中的 <code>[mysqld]</code> 節，然後輸入如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[mysqld]</span></span>
<span class="line"><span>server-id = 2</span></span>
<span class="line"><span>replicate-do-db=important</span></span>
<span class="line"><span>[ …]</span></span></code></pre></div><p>現在，我們恢復我們主資料庫的備份到從服務器的 MariaDB 上，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p &lt; /data/ important_backup.sql</span></span></code></pre></div><p>當這個恢復過程結束之後，我們將通過登入到從服務器上的 MariaDB，為資料庫 <code>important</code> 上的用户 &#39;slaveuser&#39; 授權。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRANT ALL PRIVILEGES ON important.* TO &#39;slaveuser&#39;@&#39;localhost&#39; WITH GRANT OPTION;</span></span>
<span class="line"><span>FLUSH PRIVILEGES;</span></span></code></pre></div><p>接下來，為了這個變化生效，重啓 MariaDB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart mariadb</span></span></code></pre></div><h3 id="第-4-步-啓動複製" tabindex="-1">第 4 步：啓動複製 <a class="header-anchor" href="#第-4-步-啓動複製" aria-label="Permalink to “第 4 步：啓動複製”">​</a></h3><p>記住，我們需要 <code>MASTER_LOG_FILE</code> 和 <code>MASTER_LOG_POS</code> 變量的值，它可以通過在主服務器上運行 <code>SHOW MASTER STATUS</code> 獲得。現在登入到從服務器上的 MariaDB，然後通過運行下列命令，告訴我們的從服務器它應該去哪裏找主服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STOP SLAVE;</span></span>
<span class="line"><span>CHANGE MASTER TO MASTER_HOST= &#39;192.168.1.110′, MASTER_USER=&#39;slaveuser&#39;, MASTER_PASSWORD=&#39;iamslave&#39;, MASTER_LOG_FILE=&#39;mariadb-bin.000001′, MASTER_LOG_POS=460;</span></span>
<span class="line"><span>SLAVE START;</span></span>
<span class="line"><span>SHOW SLAVE STATUS\\G;</span></span></code></pre></div><p><strong>注意：</strong> 請根據你的機器的具體情況來改變主服務器的配置。</p><h3 id="第-5-步-測試複製" tabindex="-1">第 5 步：測試複製 <a class="header-anchor" href="#第-5-步-測試複製" aria-label="Permalink to “第 5 步：測試複製”">​</a></h3><p>我們將在我們的主服務器上創建一個新表來測試主從複製是否正常工作。因此，登入到主服務器上的 MariaDB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><p>選擇資料庫為 <code>important</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>use important;</span></span></code></pre></div><p>在這個資料庫上創建一個名為 <code>test</code> 的表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>create table test (c int);</span></span></code></pre></div><p>然後在這個表中插入一些數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>insert into test (c) value (1);</span></span></code></pre></div><p>檢索剛才插入的值是否存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>select * from test;</span></span></code></pre></div><p>你將會看到剛才你插入的值已經在這個新建的表中了。</p><p>現在，我們登入到從服務器的資料庫中，查看主從複製是否正常工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>$ use important;</span></span>
<span class="line"><span>$ select * from test;</span></span></code></pre></div><p>你可以看到與前面在主服務器上的命令輸出是一樣的。因此，説明我們的主從服務工作正常，沒有發生任何問題。</p><p>我們的教程結束了，請在下面的評論框中留下你的查詢/問題。</p><hr>`,51)),i("p",null,[s[9]||(s[9]=a("via: ",-1)),t(e,{href:"http://linuxtechlab.com/creating-master-slave-replication-mariadb/"},{default:n(()=>[...s[8]||(s[8]=[a("http://linuxtechlab.com/creating-master-slave-replication-mariadb/",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("作者：",-1)),t(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>[...s[10]||(s[10]=[a("Shusain",-1)])]),_:1}),s[14]||(s[14]=a(" 譯者：",-1)),t(e,{href:"https://github.com/qhwdw"},{default:n(()=>[...s[11]||(s[11]=[a("qhwdw",-1)])]),_:1}),s[15]||(s[15]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[a("Linux中國",-1)])]),_:1}),s[20]||(s[20]=a(" 榮譽推出",-1))])])}const v=l(h,[["render",g]]);export{S as __pageData,v as default};
